      expect(h.sent).toEqual([
        {type: 'session_list', sessions: [{sessionId: 's1', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-02T00:00:00.000Z', entryCount: 2}]}
      ]);
    });

    it('answers an empty session_list when the store has no listFor', async () => {
