parameters.new_string:
async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') {
    handlePing(ws, message.timestamp);
  } else if (message.type === 'list_sessions') {
    await handleListSessions(ws, session, sessionStore, message);
  }
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: any}
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const rawSessions = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before
    });

    const sessions = rawSessions.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt.toISOString(),
      updatedAt: s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    }));

    sendJson(ws, {type: 'session_list', sessions});
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err);
    log.error('ws', 'failed to list sessions', {userId: session.userId, error});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

