async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: any}
): Promise<void> {

describe('list_sessions', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const listFor = jest.fn().mockImplementation(() => Promise.resolve([
      {sessionId: 's1', createdAt: new Date('2026-01-01T00:00:00Z'), updatedAt: new Date('2026-01-02T00:00:00Z'), entryCount: 2}
    ]));
    const h = harness([], {sessionStore: {listFor}});

    await h.send({type: 'list_sessions', limit: 10, before: {updatedAt: 123, sessionId: 's2'}, userId: 'other'});

    expect(listFor).toHaveBeenCalledWith('u1', {limit: 10, before: {updatedAt: 123, sessionId: 's2'}});
    expect(h.sent).toEqual([
      {type: 'session_list', sessions: [{sessionId: 's1', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-02T00:00:00.000Z', entryCount: 2}]}
    ]);
  });

  it('answers an empty session_list when the store has no listFor', async () => {
    const h = harness([], {sessionStore: {}});

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'session_list', sessions: []}]);
  });

  it('answers SERVER_ERROR with a ws error log when listFor throws', async () => {
    const listFor = jest.fn().mockImplementation(() => Promise.reject(new Error('database offline')));
    const h = harness([], {sessionStore: {listFor}});

    // Mock logger to verify it's called
    const {log} = await import('../../shared/logger.js');
    jest.spyOn(log, 'error').mockImplementation(() => {});

    await h.send({type: 'list_sessions'});

    expect(log.error).toHaveBeenCalledWith('ws', 'failed to list sessions', expect.objectContaining({userId: 'u1', error: 'database offline'}));
    expect(h.frames()).toEqual(['error SERVER_ERROR']);
  });
});

